    for channel in sorted(routes):
        for tag in set(routes[channel]):
            channels_by_tag.setdefault(tag, []).append(channel)

    out = []
    last_delivery = {}
    # A stable sort preserves the input order for equal timestamps.
    for timestamp, tag, message in sorted(events, key=lambda event: event[0]):
        for channel in channels_by_tag.get(tag, ()):
